<template>
  <div v-if="post" class="detail-page">
    <!-- ===== Cover ===== -->
    <div class="cover" :style="{ background: post.thumbColor }">
      <div class="cover-overlay"></div>
      <v-icon size="72" class="cover-icon">{{ post.icon }}</v-icon>
    </div>

    <!-- ===== Article ===== -->
    <div class="article-wrap">
      <div class="article-inner" :class="{ visible: pageVisible }">

        <!-- Category + Title -->
        <div class="article-header">
          <span class="category-badge">{{ post.category }}</span>
          <h1 class="article-title">{{ post.title }}</h1>
        </div>

        <!-- Author Row -->
        <div class="author-row">
          <img
            :src="post.author.avatar || exshipsLogo"
            :alt="post.author.name"
            class="author-avatar"
            loading="lazy"
            decoding="async"
          />
          <div class="author-info">
            <span class="author-name">{{ post.author.name }}</span>
            <span class="author-role">{{ post.author.role }}</span>
          </div>
          <div class="article-meta">
            <span class="meta-item">
              <v-icon size="13" class="meta-icon">mdi-calendar-outline</v-icon>
              {{ formatMonthJa(post.date) }}
            </span>
            <span class="meta-sep">·</span>
            <span class="meta-item">
              <v-icon size="13" class="meta-icon">mdi-clock-outline</v-icon>
              {{ post.readTime }}で読めます
            </span>
          </div>
        </div>

        <div class="divider"></div>

        <!-- Thumbnail -->
        <div v-if="post.thumbnail" class="thumbnail-wrap">
          <img
            :src="post.thumbnail"
            :alt="post.title"
            class="thumbnail-img"
            loading="lazy"
            decoding="async"
          />
        </div>

        <!-- Body -->
        <!-- 本文はビルド時にMarkdownから生成した静的HTML（実行時の外部入力は含まない） -->
        <div class="article-body" v-html="post.html"></div>

        <!-- Tags -->
        <div class="tags-section">
          <span
            v-for="tag in post.tags"
            :key="tag"
            class="tag"
          >#{{ tag }}</span>
        </div>

        <div class="divider"></div>

        <!-- Back Button -->
        <div class="back-wrap">
          <button class="back-btn" @click="$router.push({ name: 'blog' })">
            <v-icon size="16">mdi-arrow-left</v-icon>
            ブログ一覧に戻る
          </button>
        </div>

      </div>
    </div>
  </div>

  <!-- 記事が見つからない場合 -->
  <div v-else-if="!loading" class="not-found">
    <v-icon size="48" class="not-found-icon">mdi-alert-circle-outline</v-icon>
    <p>記事が見つかりませんでした。</p>
    <button class="back-btn" @click="$router.push({ name: 'blog' })">
      <v-icon size="16">mdi-arrow-left</v-icon>
      ブログ一覧に戻る
    </button>
  </div>
</template>

<script>
import { updateMeta } from "@/utils/meta";
import { formatMonthJa } from "@/utils/date";
import exshipsLogo from "@/assets/exshipsLogo.webp";

export default {
  name: "BlogDetailView",
  data: () => ({
    exshipsLogo,
    pageVisible: false,
    loading: true,
    post: null,
  }),
  watch: {
    // 記事から別の記事へ遷移してもコンポーネントは再利用されるため、idを監視する
    "$route.params.id"(id) {
      if (id && this.$route.name === "blog-detail") {
        this.loadPost();
      }
    },
  },
  mounted() {
    this.loadPost();
    setTimeout(() => (this.pageVisible = true), 100);
  },
  methods: {
    formatMonthJa,
    // 本文は記事ごとの遅延チャンク（一覧ページには本文が含まれない）
    async loadPost() {
      const id = this.$route.params.id;
      this.loading = true;
      try {
        const { default: post } = await import(
          /* webpackChunkName: "blog-post-[request]" */
          `@/content/blog/${id}.md`
        );
        this.post = post;
        // router.afterEach が設定する汎用メタを記事別の値で上書きする
        // （descriptionの整形は scripts/generate-seo-pages.js の静的生成と揃える）
        updateMeta({
          title: post.title,
          description: (post.excerpt || post.title).slice(0, 120),
          path: this.$route.path,
          type: "article",
        });
      } catch (e) {
        this.post = null;
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

